JavaScript<pre><code>import httpClient from './httpClient';

const endpoint = '/courses'; // Endpoint específic de cursos

export const getAllCourses = async () =&gt; {
  const response = await httpClient.get(endpoint);
  return response.data; // Retorna les dades de la resposta
};

export const getCourseById = async (id) =&gt; {
  const response = await httpClient.get(`${endpoint}/${id}`);
  return response.data;
};

export const createCourse = async (course) =&gt; {
  const response = await httpClient.post(endpoint, course);
  return response.data;
};

export const updateCourse = async (id, course) =&gt; {
  const response = await httpClient.put(`${endpoint}/${id}`, course);
  return response.data;
};

export const deleteCourse = async (id) =&gt; {
  const response = await httpClient.delete(`${endpoint}/${id}`);
  return response.data;
};
</code></pre>

Vue<pre><code>&lt;template&gt;
  &lt;div&gt;
    &lt;h1&gt;Llistat de cursos&lt;/h1&gt;
    &lt;ul&gt;
      &lt;li v-for="course in courses" :key="course.id"&gt;
        {{ course.name }} - {{ course.duration }}
        &lt;button @click="deleteCourse(course.id)"&gt;Esborrar&lt;/button&gt;
      &lt;/li&gt;
    &lt;/ul&gt;
  &lt;/div&gt;
&lt;/template&gt;

&lt;script&gt;
import { getAllCourses, deleteCourse } from '../api/coursesService';

export default {
  name: 'CourseList',
  data() {
    return {
      courses: [],
    };
  },
  async created() {
    // Carrega els cursos quan es monte el component
    this.courses = await getAllCourses();
  },
  methods: {
    async deleteCourse(id) {
      try {
        await deleteCourse(id);
        this.courses = this.courses.filter(course =&gt; course.id !== id);
      } catch (error) {
        console.error('Error esborrant el curs:', error);
      }
    },
  },
};
&lt;/script&gt;
</code></pre>

Vue<pre><code>&lt;template&gt;
  &lt;div&gt;
    &lt;h1&gt;{{ isEditing ? 'Editar curs' : 'Afegir curs' }}&lt;/h1&gt;
    &lt;form @submit.prevent="submitForm"&gt;
      &lt;input v-model="course.name" placeholder="Nom del curs" required /&gt;
      &lt;input v-model="course.duration" placeholder="Duració" required /&gt;
      &lt;button type="submit"&gt;Guardar&lt;/button&gt;
    &lt;/form&gt;
  &lt;/div&gt;
&lt;/template&gt;

&lt;script&gt;
import { createCourse, updateCourse, getCourseById } from '../api/coursesService';

export default {
  name: 'CourseForm',
  props: {
    courseId: {
      type: Number,
      default: null, // Si és `null`, estem creant un nou curs
    },
  },
  data() {
    return {
      course: {
        name: '',
        duration: '',
      },
    };
  },
  computed: {
    isEditing() {
      return this.courseId !== null;
    },
  },
  async created() {
    // Si estem editant, carrega les dades del curs
    if (this.isEditing) {
      this.course = await getCourseById(this.courseId);
    }
  },
  methods: {
    async submitForm() {
      try {
        if (this.isEditing) {
          await updateCourse(this.courseId, this.course);
        } else {
          await createCourse(this.course);
        }
        alert('Curs guardat amb èxit!');
        this.$router.push('/');
      } catch (error) {
        console.error('Error guardant el curs:', error);
      }
    },
  },
};
&lt;/script&gt;
</code></pre>
